Tool response:
Tool: find_boards
Description: Filter boards.name by the supplied name and return matching IDs and names.
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "Board name",
          "title": "Name"
        }
      },
      "required": [
        "name"
      ]
    }

Tool response:
Tool: find_tags_on_board
Description: Filter tags.name by the supplied name for the given board_id and return matching IDs and names.
Parameters:
    {
      "type": "object",
      "properties": {
        "board_id": {
          "type": "integer",
          "title": "Board Id",
          "description": ""
        },
        "name": {
          "type": "string",
          "description": "Tag name",
          "title": "Name"
        }
      },
      "required": [
        "board_id",
        "name"
      ]
    }

Tool response:
Tool: delete_tag_from_board
Description: Deletes the tag with the given tag_id from the board identified by board_id.
Parameters:
    {
      "type": "object",
      "properties": {
        "board_id": {
          "type": "integer",
          "title": "Board Id",
          "description": ""
        },
        "tag_id": {
          "type": "integer",
          "title": "Tag Id",
          "description": ""
        }
      },
      "required": [
        "board_id",
        "tag_id"
      ]
    }

